// The branch a card is built on, and what the builder did put on it.
import { run, stageAllButSettings } from "@software-factory/core";
// The same branch a prototype of the card is pushed to while planning (the
// plan skill), so the build continues it.
export function branchOf(number) {
    return `factory/issue-${String(number)}`;
}
// Commits whatever the builder left uncommitted (never a settings file) and
// puts the copy's work on the card's branch on GitHub.
export async function commitAndPush(folder, branch, message) {
    const git = (...args) => run("git", ["-C", folder, ...args], { env: { LEFTHOOK: "0" } });
    if ((await git("status", "--porcelain")).trim() !== "") {
        await stageAllButSettings(folder);
        await git("commit", "--quiet", "-m", message);
    }
    await git("push", "--quiet", "--force", "origin", `HEAD:refs/heads/${branch}`);
}
